package app.onklav.home

import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

@RunWith(RobolectricTestRunner::class)
@Config(sdk=[29])
class SdkRecurrenceTest{
 private fun args(start:String="2026-03-07T09:00:00",frequency:String="daily",count:Int=3)=JSONObject().put("start",start).put("timezone","America/Chicago").put("frequency",frequency).put("interval",1).put("count",count).put("duration_seconds",3600).put("window_start_ms",0).put("window_end_ms",253402300799999L).put("limit",200).put("gap","skip").put("overlap","earlier")
 @Test fun localDailyTimeSurvivesDstAndTimedDurationStaysElapsed(){val rows=SdkRecurrence.expand(args()).getJSONArray("occurrences");assertEquals(3,rows.length());val a=rows.getJSONObject(0);val b=rows.getJSONObject(1);assertEquals(23*3600_000L,b.getLong("start_ms")-a.getLong("start_ms"));assertEquals(3600_000L,b.getLong("end_ms")-b.getLong("start_ms"));assertEquals("2026-03-08T09:00:00",b.getString("local_start"));assertEquals(-18000,b.getInt("offset_seconds"))}
 @Test fun gapAndOverlapPoliciesAreExplicitAndCountOnlyRealOccurrences(){val skip=SdkRecurrence.expand(args("2026-03-07T02:30:00")).getJSONArray("occurrences");assertEquals("2026-03-09T02:30:00",skip.getJSONObject(1).getString("local_start"));val forward=SdkRecurrence.expand(args("2026-03-07T02:30:00").put("gap","forward")).getJSONArray("occurrences");assertEquals("2026-03-08T03:30:00",forward.getJSONObject(1).getString("local_start"));val early=SdkRecurrence.expand(args("2026-11-01T01:30:00",count=1)).getJSONArray("occurrences").getJSONObject(0);val late=SdkRecurrence.expand(args("2026-11-01T01:30:00",count=1).put("overlap","later")).getJSONArray("occurrences").getJSONObject(0);assertEquals(3600_000L,late.getLong("start_ms")-early.getLong("start_ms"))}
 @Test fun monthAndLeapYearRecurrenceSkipInvalidDatesInsteadOfClamping(){val monthly=SdkRecurrence.expand(args("2026-01-31T09:00:00","monthly")).getJSONArray("occurrences");assertEquals("2026-03-31T09:00:00",monthly.getJSONObject(1).getString("local_start"));assertEquals("2026-05-31T09:00:00",monthly.getJSONObject(2).getString("local_start"));val leap=SdkRecurrence.expand(args("2028-02-29T09:00:00","yearly",2)).getJSONArray("occurrences");assertEquals("2032-02-29T09:00:00",leap.getJSONObject(1).getString("local_start"))}
 @Test fun allDayIntervalsUseCivilDatesAcrossShortLongAndMissingDays(){fun day(start:String,zone:String="America/Chicago"):JSONObject{val a=args(start,count=1);a.remove("duration_seconds");return SdkRecurrence.expand(a.put("duration_days",1).put("timezone",zone)).getJSONArray("occurrences").getJSONObject(0)};val spring=day("2026-03-08T00:00:00");assertEquals(23*3600_000L,spring.getLong("end_ms")-spring.getLong("start_ms"));val fall=day("2026-11-01T00:00:00");assertEquals(25*3600_000L,fall.getLong("end_ms")-fall.getLong("start_ms"));val midnight=day("2018-11-04T00:00:00","America/Sao_Paulo");assertEquals("2018-11-04T01:00:00",midnight.getString("local_start"));val a=args("2011-12-30T00:00:00",count=1);a.remove("duration_seconds");val skipped=SdkRecurrence.expand(a.put("duration_days",1).put("timezone","Pacific/Apia")).getJSONArray("occurrences");assertEquals("2011-12-31T00:00:00",skipped.getJSONObject(0).getString("local_start"))}
 @Test fun windowLimitsAndWorkLimitsAreVisibleAndInvalidRulesFail(){val full=SdkRecurrence.expand(args());val rows=full.getJSONArray("occurrences");val cut=args().put("window_start_ms",rows.getJSONObject(1).getLong("start_ms")).put("window_end_ms",rows.getJSONObject(2).getLong("start_ms"));assertEquals(1,SdkRecurrence.expand(cut).getJSONArray("occurrences").length());assertTrue(SdkRecurrence.expand(args().put("limit",1)).getBoolean("truncated"));for(a in listOf(args().put("count",1001),args().put("timezone","Unknown/Zone"),args().put("rrule","FREQ=DAILY"),args().put("start","2026-02-30T09:00:00"),args().put("window_end_ms",0),args().put("interval",0))){assertThrows(Exception::class.java){SdkRecurrence.expand(a)}};assertEquals("+00:00",SdkRecurrence.expand(args().put("timezone","+00:00")).getString("timezone"))}
}
